import React from 'react';
import { NavLink } from 'react-router-dom';
import './Navbar.css';

export default function Navbar() {
  return (
    <nav className="navbar">
      <div className="navbar-logo">
        🏃‍♂️ Run Run Run
      </div>
      <ul className="navbar-links">
        <li>
          <NavLink to="/" className={({ isActive }) => isActive ? 'active' : ''}>Home</NavLink>
        </li>
        <li>
          <NavLink to="/create-runner" className={({ isActive }) => isActive ? 'active' : ''}>Create Runner</NavLink>
        </li>
        <li>
          <NavLink to="/manage-runner" className={({ isActive }) => isActive ? 'active' : ''}>Manage Runner</NavLink>
        </li>
      </ul>
    </nav>
  );
}
